import type { CalculatorSpec } from './types'

/**
 * What the v29 vault costs in keys: one level of an upgrade, a run of levels, a category's unlock,
 * and what is left of a whole tab.
 *
 * Kept apart from the `vault.*` entries in `specs-costs.ts`, which price the Power and Harmony
 * trees as they were before v29. The two share no ids: an old node is `defabs`, a v29 upgrade is
 * `v29:power:Defense:Defense Absolute`, the key a save's `vault.v29.levels` uses.
 */

const KEYS = 'src/mechanics/vault/keys.ts'

export const VAULT_V29_CALCULATORS: readonly CalculatorSpec[] = [
  {
    id: 'vault.v29.upgradeKeysCost',
    title: 'Keys for one level of a v29 vault upgrade',
    entry: 'mechanics',
    module: KEYS,
    symbol: 'vaultV29UpgradeKeysCost',
    because:
      'v29 rebuilt the vault as Harmony, Power and Enemy categories with a key price for every level, '
      + 'and raised prices over the old trees. This is the price a current account pays.',
    params: [
      {
        name: 'upgrade',
        kind: 'string',
        describes: 'row key "v29:<tree>:<category>:<name>" — "v29:power:Defense:Defense Absolute", '
          + '"v29:enemy:Simple:Basic:Attack (-1%)"; the keys of a save\'s vault.v29.levels',
      },
      { name: 'level', kind: 'number', describes: 'the level being bought, from 1' },
    ],
    returns: { kind: 'number', unit: 'keys', nullable: true, describes: 'keys for that level' },
    invariants: [
      'returns null for an unknown row key and for a level the upgrade does not have',
      'does not include the category unlock',
    ],
    reads: ['vault.v29.upgrade', 'vault.v29.upgradeLevel'],
    produces: ['vault.v29.upgradeKeysCost'],
    dependsOn: [],
  },
  {
    id: 'vault.v29.upgradeKeysBetween',
    title: 'Keys to take a v29 vault upgrade from one level to another',
    entry: 'mechanics',
    module: KEYS,
    symbol: 'vaultV29UpgradeKeysBetween',
    because: 'What the rest of an upgrade costs, and the piece the v29 whole-tree total is built from.',
    params: [
      { name: 'upgrade', kind: 'string', describes: 'row key "v29:<tree>:<category>:<name>"' },
      { name: 'fromLevel', kind: 'number', describes: 'current level, 0 when unbought' },
      { name: 'toLevel', kind: 'number', describes: 'target level' },
    ],
    returns: { kind: 'number', unit: 'keys', nullable: true, describes: 'total keys' },
    invariants: [
      'returns 0 when toLevel equals fromLevel',
      'returns null rather than a partial total for a level the upgrade does not have, an unknown '
      + 'row key, a fractional level, or toLevel below fromLevel',
    ],
    reads: ['vault.v29.upgrade', 'vault.v29.upgradeLevel', 'vault.v29.upgradeKeysCost'],
    produces: ['vault.v29.upgradeKeysBetween'],
    dependsOn: ['vault.v29.upgradeKeysCost'],
  },
  {
    id: 'vault.v29.categoryUnlockKeys',
    title: 'Keys to unlock a v29 vault category',
    entry: 'mechanics',
    module: KEYS,
    symbol: 'vaultV29CategoryUnlockKeys',
    because:
      'A category is unlocked once with keys before any of its upgrades can be bought, so the first '
      + 'upgrade in a new category costs its unlock as well.',
    params: [
      { name: 'tree', kind: 'string', describes: '"harmony", "power" or "enemy"' },
      { name: 'category', kind: 'string', describes: 'category name — "Defense", "Cards", "Simple"' },
    ],
    returns: { kind: 'number', unit: 'keys', nullable: true, describes: 'keys to unlock it; 0 when it is open from the start' },
    invariants: ['returns null for an unknown tree or category'],
    reads: ['vault.v29.category'],
    produces: ['vault.v29.categoryUnlockKeys'],
    dependsOn: [],
  },
  {
    id: 'vault.v29.treeKeysRemaining',
    title: 'Keys still to spend to finish a v29 vault tree',
    entry: 'mechanics',
    module: KEYS,
    symbol: 'vaultV29TreeKeysRemaining',
    because:
      'Keys are scarce and the trees are long, so "how far am I from done" is the planning question. '
      + 'It takes the levels a save reports as they are. A misspelt key is refused, because counting '
      + 'it as unbought would quietly inflate the answer.',
    params: [
      { name: 'tree', kind: 'string', describes: '"harmony", "power" or "enemy"' },
      {
        name: 'levels',
        kind: 'object',
        optional: true,
        describes: 'row key to its current level, and "v29:<tree>:<category>:__unlock__" to 1 for an '
          + 'unlocked category; a key left out is unbought, and keys of the other trees are ignored',
      },
    ],
    returns: { kind: 'number', unit: 'keys', nullable: true, describes: 'keys for every remaining category unlock and upgrade level' },
    invariants: [
      'with no levels it is the tree\'s whole price, every unlock and every level',
      'never rises as a level rises',
      'returns null for any other tree name, a key of this tree that names no row, or a level a row cannot be at',
    ],
    reads: ['vault.v29.upgrade', 'vault.v29.upgradeLevel', 'vault.v29.category', 'vault.v29.upgradeKeysBetween'],
    produces: ['vault.v29.treeKeysRemaining'],
    dependsOn: ['vault.v29.upgradeKeysBetween'],
  },
]
